\rowcolor{bleusecondaire!15}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\large Exercice 1 \hspace{0.2cm}\textbullet\hspace{0.2cm} Algèbre et Arithmétique / Suites}} \hfill \bfseries 4 points \\* \midrule[0.6pt]

\textbf{Q.1} & Arithmétique / Divisibilité &
\vrai\newline
\textbullet\ \subpt{0,50} Écriture $3^{2n}-1 = 9^n - 1$.\newline
\textbullet\ \subpt{0,50} Factorisation $(9-1)(9^{n-1}+\dots+1) = 8K$ : \repbox{Divisible par 8}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{Q.2} & Suites numériques &
\vrai\newline
\textbullet\ \subpt{0,50} Point fixe $L = \frac{1}{2}L + 3 \implies L = 6$.\newline
\textbullet\ \subpt{0,50} Convergence monotone : \repbox{Converge vers 6}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{Q.3} & Nombres complexes &
\vrai\newline
\textbullet\ \subpt{0,50} Traduction géométrique $MA = MB$.\newline
\textbullet\ \subpt{0,50} Équation de la médiatrice : \repbox{y = -x}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{Q.4} & Analyse / Convexité &
\vrai\newline
\textbullet\ \subpt{0,50} Dérivée seconde $f''(x) = (x-2)\mathrm{e}^{-x}$.\newline
\textbullet\ \subpt{0,50} Changement de signe en $x=2$ : \repbox{Unique point d'inflexion}. & \pts{1,00} \\

\midrule[1pt]

\rowcolor{bleusecondaire!15}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\large Exercice 2 \hspace{0.2cm}\textbullet\hspace{0.2cm} Géométrie dans l'espace}} \hfill \bfseries 5 points \\* \midrule[0.6pt]

