\textbullet\ \subpt{0,25} Identification des 8 sommets.\newline
\textbullet\ \subpt{0,25} Écriture rigoureuse : \repbox{A(0,0,0), G(1,1,1)}. & \pts{0,50} \\
\cmidrule(lr){2-4}
\textbf{A.2} & Orthogonalité et produit scalaire &
\textbullet\ \subpt{0,50} Calcul de $\vec{BD}$ et $\vec{BE}$.\newline
\textbullet\ \0,50 Produits scalaires nuls : \repbox{\vec{n} \perp \text{plan }(BDE)}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{A.3} & Équation cartésienne de plan &
\textbullet\ \subpt{0,50} Forme $x+y-z+d=0$.\newline
\textbullet\ \subpt{0,50} Détermination de $d$ : \repbox{x+y-z-1 = 0}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{A.4} & Position relative point/plan &
\textbullet\ \subpt{0,50} Coordonnées de $I(\frac{1}{2}, \frac{1}{2}, \frac{1}{2})$.\newline
\textbullet\ \subpt{0,50} Vérification : \repbox{Appartenance confirmée}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{A.5} & Distance point à un plan &
\textbullet\ \subpt{0,75} Application de la formule de distance.\newline
\textbullet\ \subpt{0,75} Résultat et interprétation : \repbox{d(G, (BDE)) = 0}. & \pts{1,50} \\

\midrule[1pt]

\rowcolor{bleusecondaire!15}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\large Exercice 3 \hspace{0.2cm}\textbullet\hspace{0.2cm} Analyse et Fonctions}} \hfill \bfseries 6 points \\* \midrule[0.6pt]

\rowcolor{bleusecondaire!10}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\textsc{Partie A}} \;\textbullet\; \textcolor{bleuprimaire}{Étude de la fonction auxiliaire $g$}} \hfill \textcolor{bleusecondaire}{\bfseries 2,00 points} \\* \midrule[0.5pt]

\textbf{A.1} & Dérivée de $g$ &
\textbullet\ \subpt{0,50} Calcul $g'(x) = 2x - \frac{2}{x}$.\newline
\textbullet\ \subpt{0,50} Étude du signe sur $]0\,;\,+\infty[$ : \repbox{Décroissante puis croissante}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{A.2} & Variations de $g$ &
\textbullet\ \subpt{0,50} Minimum atteint en $x=1$ égal à $0$ : \repbox{g(1) = 0}. & \pts{0,50} \\
\cmidrule(lr){2-4}
\textbf{A.3} & Signe de $g$ &
\textbullet\ \subpt{0,50} Justification $g(x) \ge 0$ pour tout $x > 0$ : \repbox{g(x) \ge 0}. & \pts{0,50} \\

\midrule[0.6pt]
\rowcolor{bleusecondaire!10}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\textsc{Partie B}} \;\textbullet\; \textcolor{bleuprimaire}{Étude de la fonction principale $f$}} \hfill \textcolor{bleusecondaire}{\bfseries 4,00 points} \\* \midrule[0.5pt]

\textbf{B.1} & Limites en $0^+$ &
\textbullet\ \subpt{0,50} Calcul de limite et asymptote : \repbox{-\infty, x=0 \text{ asymptote}}. & \pts{0,50} \\
\cmidrule(lr){2-4}
\textbf{B.2} & Limites en $+\infty$ &
\textbullet\ \subpt{0,50} Utilisation des croissances comparées : \repbox{+\infty}. & \pts{0,50} \\
\cmidrule(lr){2-4}
\textbf{B.3} & Dérivée de $f$ &
\textbullet\ \subpt{0,75} Expression algébrique et lien avec $g$ : \repbox{f'(x) = g(x)/x^2}. & \pts{0,75} \\
\cmidrule(lr){2-4}
\textbf{B.4} & Variations de $f$ &
\textbullet\ \subpt{0,75} Signe de $f'$ et tableau de variations : \repbox{Strictement croissante}. & \pts{0,75} \\
\cmidrule(lr){2-4}
\textbf{B.5} & Asymptote oblique &
\textbullet\ \subpt{0,50} Différence tendant vers 0.\newline
\textbullet\ \subpt{0,50} Position relative : \repbox{y = x - 1 asymptote}. & \pts{1,00} \\

\midrule[1pt]

\rowcolor{bleusecondaire!15}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\large Exercice 4 \hspace{0.2cm}\textbullet\hspace{0.2cm} Probabilités}} \hfill \bfseries 5 points \\* \midrule[0.6pt]

\rowcolor{bleusecondaire!10}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\textsc{Partie A}} \;\textbullet\; \textcolor{bleuprimaire}{Loi binomiale}} \hfill \textcolor{bleusecondaire}{\bfseries 3,00 points} \\* \midrule[0.5pt]

\textbf{A.1} & Modélisation loi binomiale &
\textbullet\ \subpt{0,50} Répétition d'épreuves identiques et indépendantes.\newline
\textbullet\ \subpt{0,50} Paramètres : \repbox{B(50, 0,05)}. & \pts{1,00} \\
\cmidrule(lr){2-4}
\textbf{A.2} & Calcul de probabilité exacte &
\textbullet\ \subpt{0,75} Application de la formule et calcul : \repbox{P(X=3) \approx 0,219}. & \pts{0,75} \\
\cmidrule(lr){2-4}
\textbf{A.3} & Événement contraire &
\textbullet\ \subpt{0,75} Calcul $1 - P(X=0)$ : \repbox{P(X \ge 1) \approx 0,923}. & \pts{0,75} \\
\cmidrule(lr){2-4}
\textbf{A.4} & Espérance mathématique &
\textbullet\ \subpt{0,50} Calcul $E(X) = np$ et interprétation : \repbox{E(X) = 2,5}. & \pts{0,50} \\

\midrule[0.6pt]
\rowcolor{bleusecondaire!10}
\multicolumn{4}{l}{\bfseries\textcolor{bleuprimaire}{\textsc{Partie B}} \;\textbullet\; \textcolor{bleuprimaire}{Inéquations et seuils}} \hfill \textcolor{bleusecondaire}{\bfseries 2,00 points} \\* \midrule[0.5pt]

\textbf{B.1} & Expression générale &
\textbullet\ \subpt{0,50} Formule en fonction de $n$ : \repbox{1 - 0,95^n}. & \pts{0,50} \\
\cmidrule(lr){2-4}
\textbf{B.2} & Résolution d'inéquation &
\textbullet\ \subpt{0,75} Utilisation du logarithme népérien.\newline
\textbullet\ \subpt{0,75} Conclusion sur la taille minimale : \repbox{n = 59}. & \pts{1,50} \\

